#include "stdlib/blas/ext/base/ndarray/sdiff.h"
#include "stdlib/blas/ext/base/sdiff.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/base/bytes_per_element.h"
#include <stdint.h>

/**
* Calculates the k-th discrete forward difference of a one-dimensional single-precision floating-point ndarray.
*
* @param arrays   array containing six ndarrays: input ndarray, prepend ndarray, append ndarray, output ndarray, workspace ndarray, and scalar k ndarray
*/
void stdlib_blas_ext_sdiff( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];
	const struct ndarray *prepend = arrays[ 1 ];
	const struct ndarray *append = arrays[ 2 ];
	const struct ndarray *out = arrays[ 3 ];
	const struct ndarray *w = arrays[ 4 ];
	const struct ndarray *k = arrays[ 5 ];

	const int32_t kval = *(int32_t *)stdlib_ndarray_data( k );

	stdlib_strided_sdiff_ndarray(
		stdlib_ndarray_length( x ),
		kval,
		(const float *)stdlib_ndarray_data( x ),
		stdlib_ndarray_strides( x )[ 0 ] / sizeof( float ),
		stdlib_ndarray_offset( x ),
		stdlib_ndarray_length( prepend ),
		(const float *)stdlib_ndarray_data( prepend ),
		stdlib_ndarray_strides( prepend )[ 0 ] / sizeof( float ),
		stdlib_ndarray_offset( prepend ),
		stdlib_ndarray_length( append ),
		(const float *)stdlib_ndarray_data( append ),
		stdlib_ndarray_strides( append )[ 0 ] / sizeof( float ),
		stdlib_ndarray_offset( append ),
		(float *)stdlib_ndarray_data( out ),
		stdlib_ndarray_strides( out )[ 0 ] / sizeof( float ),
		stdlib_ndarray_offset( out ),
		(float *)stdlib_ndarray_data( w ),
		stdlib_ndarray_strides( w )[ 0 ] / sizeof( float ),
		stdlib_ndarray_offset( w )
	);
}
